// Before a card's pull request, a record the branch adds (a run file under
// `runs/`) is named after its card: `runs/issue-12-short-name.md` for card
// 12. Two cards then never share a name, whatever is built at the same time.
// Records that are already there (`001-…`) are never looked at: only the
// files the branch adds.
const RECORD = /(?:^|\/)runs\/([^/]+\.md)$/;
// The records among the added files that are not named after the card.
export function recordsNotNamed(card, added) {
    const prefix = `issue-${String(card)}-`;
    return added.filter((file) => {
        const name = RECORD.exec(file)?.[1];
        return (name !== undefined && name !== "README.md" && !name.startsWith(prefix));
    });
}
// What the builder is told when a record is not named after its card.
export function recordsNamedReport(card, wrong) {
    if (wrong.length === 0)
        return "";
    const number = String(card);
    const list = wrong.map((file) => `- \`${file}\``).join("\n");
    return `### Records not named after card #${number}\n\nEvery record is named after its card: \`runs/issue-${number}-short-name.md\`. Rename (\`git mv\`) and fix the links to it:\n\n${list}`;
}
